// Мозг страницы (как у Aquora): готовые ответы и знания по темам (англ. и рус.) — отвечают и без сервера.
window.LOCAL_QA={"how is a farmer's debt calculated?": {"answer": "A farmer's debt is calculated as the difference between the total billed amounts for actually delivered water and the confirmed payments made through the bank.", "screen": "billing", "a": "7e065334f15cbf931558", "steps": [{"screen": "contracts", "text": "A delivery acceptance act records the actual volume of water supplied to the farmer's plot.", "a": "8124023ac4488f6b45ac"}, {"screen": "billing", "text": "IMIS calculates the charge by multiplying the actual delivered volume by the approved tariff of 5 dirams per cubic metre.", "a": "ecbb011abfc7cfafccd3"}, {"screen": "billing", "text": "Payments completed through the bank are credited against the specific open bills.", "a": "aaa60d597f0325701502"}, {"screen": "billing", "text": "Any unpaid balance remaining after the ten-day payment period is recorded as active debt.", "a": "f2e8d699330787ad7c13"}]}, "what happens if a farmer does not pay on time?": {"answer": "If a farmer fails to pay by the deadline, the debt is recorded in IMIS, and the farmer and their WUA receive notifications. If the debt remains unpaid after 30 days, the case is transferred to the legal department for further action. Water supply is not cut off, as the system focuses on debt recovery through legal and administrative procedures.", "screen": "billing", "a": "63ab16ba27d506984de8", "steps": [{"screen": "billing", "text": "The system identifies the debt as the difference between the billed amount and the payment received after the 10-day deadline.", "a": "b4e017c40b30404126f2"}, {"screen": "billing", "text": "IMIS sends notifications to the farmer and the WUA regarding the outstanding balance.", "a": "c4ec6bcb6605ece94ccb"}, {"screen": "billing", "text": "If the debt persists for 30 days, the case is officially transferred to the legal department for formal recovery.", "a": "c1737d3f34e0aba81c21"}]}, "what happens if a farmer does not pay on time and the debt grows?": {"answer": "If a farmer fails to pay by the deadline, the debt is recorded in IMIS, and the farmer and their WUA are notified. If the debt persists for 30 days after the payment deadline, the case is transferred to the legal department for further action. The system continues to track the debt and any subsequent payments, and water supply is not cut off based solely on the debt status.", "screen": "billing", "a": "6f0a033117456072204e", "steps": [{"screen": "billing", "text": "The system identifies the debt as the difference between the invoiced amount and the payments received after the 10-day payment period.", "a": "dcb8151ecc937bb4e0b8"}, {"screen": "billing", "text": "IMIS sends notifications to the farmer and the WUA regarding the outstanding balance.", "a": "c4ec6bcb6605ece94ccb"}, {"screen": "billing", "text": "If the debt remains unpaid for 30 days, the case is formally transferred to the legal department for processing.", "a": "e9cbf8c67ba6c16b9373"}, {"screen": "billing", "text": "Any subsequent payments are recorded in IMIS, automatically reducing the debt and updating the status of the case.", "a": "6de7643664bd8881da38"}]}, "how are water readings taken?": {"answer": "In IMIS, water readings are captured by inspectors using the mobile app or transmitted automatically through connected telemetry sensors.", "screen": "readings", "a": "d6d73006669d66faf799", "steps": [{"screen": "readings", "text": "Inspectors visit gauging stations and record water level readings in the IMIS mobile app along with a photo, GPS location, and timestamp.", "a": "eeab5ec570b3a3755ba5"}, {"screen": "readings", "text": "If operating offline, the mobile app queues the reading on the device and submits it automatically when the connection is restored.", "a": "2ac0897ed59d07bc7de1"}, {"screen": "readings", "text": "Automated level sensors and flow meters can also transmit readings directly into IMIS via the telemetry API.", "a": "fe6debb7b93fa98dae4d"}, {"screen": "readings", "text": "IMIS converts water levels to flow using rating curves and calculates volume based on the difference from the previous reading.", "a": "42826130e466867a12bd"}]}, "what does the sentinel-2 check do?": {"answer": "The Sentinel-2 satellite check compares the vegetation index (NDVI) of a plot against the reference value for the declared crop in that specific ten-day period. Cloud cover is considered during the analysis, and plots require an outlined border on the map to be checked. A mismatch is never an automatic penalty, but rather grounds to dispatch an inspector to examine the field.", "screen": "satellite", "a": "f832674be767776e8c21", "steps": []}, "how do complaints move up?": {"answer": "Complaints are initially submitted to the organization directly above the WUA and automatically escalate to higher administrative levels if not resolved within the designated timeframe.", "screen": "complaints", "a": "3fc8c3fff8529d1fa098", "steps": [{"screen": "complaints", "text": "The water user files a complaint in the mobile app, which is submitted to the organization directly above their WUA.", "a": "8f9074432069c1921c26"}, {"screen": "complaints", "text": "An assigned officer reviews the issue and sets the complaint status to 'in progress'.", "a": "de1f786e7ffb05df9537"}, {"screen": "complaints", "text": "If the issue is not handled within the allowed timeframe or authority, the system escalates it to the next higher organization.", "a": "258bcfd4ca72eba48459"}, {"screen": "complaints", "text": "The complaint retains its original submission date, and the water user tracks updates directly in the app until it is resolved.", "a": "b8d9ddf10803d7150e30"}]}, "what does the link scheme show?": {"answer": "In IMIS, the link scheme illustrates how organizations are connected to the water objects they serve. It offers four distinct views: organization-to-object links, where clicking a node allows you to link or unlink it; the tree of organizations; the tree of water objects; and the comprehensive IMIS model. This model visualizes water bodies, organizations, and water users based on their active links.", "screen": "links", "a": "fc7c92aac7070f5c9fb2", "steps": []}, "how is the water use plan built?": {"answer": "The water use plan is calculated across 36 ten-day periods by combining crop rotation data with specific hydromodule irrigation norms.", "screen": "norms", "a": "1754da335714c6266df0", "steps": [{"screen": "norms", "text": "Before the season, the Water User Association enters crop rotation details, including crops and sown areas for each plot.", "a": "c58fcf558a64079a6402"}, {"screen": "norms", "text": "IMIS matches each crop with the irrigation norm defined for the plot's hydromodule district.", "a": "2083e171671919caccd5"}, {"screen": "norms", "text": "The system multiplies the area by the norm to determine the required water volume for each of the 36 ten-day periods in the year.", "a": "57711222cf29b489b08b"}, {"screen": "norms", "text": "Individual plot requirements roll up automatically through the organizational hierarchy to national summaries.", "a": "94e177daf5744408dedb"}]}, "what is imis?": {"answer": "IMIS is the Irrigation Management Information System of the Agency of Melioration and Irrigation (AMI) of the Republic of Tajikistan. It automates water accounting, planning, dispatching, and billing from individual agricultural plots up to the national level. The system unites water users, water user associations, and AMI departments to ensure transparent distribution and efficient irrigation management across the country.", "screen": "intro", "a": "e473cc3bf5b1d7c6b256", "steps": []}, "who can see what in imis?": {"answer": "In IMIS, data visibility is determined by the organizational hierarchy: every user sees data from their own organization and all units subordinate to it. National authorities (AMI) can view data for the entire country, regional and basin departments see their territory, and Water User Associations (WUAs) see only their association. Water users (farmers) can view only their own personal account, plots, contracts, requests, and bills. Specific roles like inspectors, dispatchers, or financiers access relevant functions within their organizational boundary, and administrators can grant personal permissions when needed.", "screen": "orgs", "a": "c7b2722b62d8e5fed624", "steps": []}, "how does a farmer get water?": {"answer": "A farmer receives irrigation water by submitting a ten-day request under an active contract, which is approved into the delivery schedule and confirmed upon supply.", "screen": "contracts", "a": "5d51e741b43fe754b6fa", "steps": [{"screen": "contracts", "text": "The farmer signs a tripartite contract with the WUA and the higher department for registered plots.", "a": "a459569579c004b89118"}, {"screen": "contracts", "text": "Every ten days, the farmer submits a water request specifying the plot, crop, and sown area via the mobile app or website.", "a": "271c277bd4c239ef361f"}, {"screen": "dispatch", "text": "The request is reviewed and approved into the water distribution schedule by the authorized department.", "a": "23f5312954371baf9850"}, {"screen": "billing", "text": "Water is delivered to the plot, and a delivery act records the actual received volume.", "a": "0051226fed13e54af893"}]}, "what is a hydromodule district?": {"answer": "A hydromodule district is a classification based on groundwater depth and soil texture rather than administrative boundaries, determining how much water a crop requires per hectare. IMIS uses nine hydromodule districts (I to IX) defined by three groundwater depth ranges and three soil types: sandy, loamy, and clay. Where groundwater is close to the surface, roots receive moisture from below and need less applied irrigation. In IMIS, each crop and hydromodule district pair defines the specific net and gross irrigation norms calculated under the FAO and CROPWAT methodology.", "screen": "norms", "a": "c7edefdf85cce9583e3f", "steps": []}, "how does payment through the bank work?": {"answer": "Payments are processed strictly through the bank using the water user's unique personal account number to select and settle open bills.", "screen": "billing", "a": "0a19f30bd88197ecf86d", "steps": [{"screen": "billing", "text": "The bank sends the water user's unique personal account number to IMIS.", "a": "adffabcfac1418a00ca8"}, {"screen": "billing", "text": "IMIS returns the open bills indicating the WUA, contract, and amount due.", "a": "198ae1386b3f2621c0ea"}, {"screen": "billing", "text": "The payer selects the specific bill to pay, without the possibility of overpaying or searching for other users.", "a": "a06a6a0c68ade4a73d12"}, {"screen": "billing", "text": "Upon bank confirmation, IMIS books the payment to the bill, preventing duplicate postings and handling errors by reversal.", "a": "2385aae890efc9f7baf3"}]}, "what happens if a reading is wrong?": {"answer": "In IMIS, entered readings undergo automated validation: cumulative flow meter readings cannot decrease, and water level changes cannot exceed plausible limits for that cross-section. Suspect readings that fail validation are not discarded, but are saved with a flag requiring confirmation. Because inspector entries require a gauge photo, GPS coordinates, and a timestamp, any discrepancy can be verified against the physical evidence and investigated.", "screen": "readings", "a": "b64bda140e5bc09471bd", "steps": []}, "does the mobile app work offline?": {"answer": "Yes, the IMIS mobile app supports offline functionality for specific tasks. Gauging station readings taken by inspectors and complaints submitted by water users are queued locally on the mobile device when there is no network connection. These queued records are automatically transmitted to the system as soon as the connection is restored.", "screen": "admin", "a": "3767a98553c6930834b3", "steps": []}, "how are water losses measured?": {"answer": "IMIS measures water losses by comparing water intake from the source against volumes delivered to farm plots across the canal network.", "screen": "balance", "a": "2b2d27798aaf7c107ce2", "steps": [{"screen": "readings", "text": "Water intake from the river or reservoir is measured at the headworks gauging station.", "a": "b23c2c3070090f24a803"}, {"screen": "readings", "text": "Water supplied into the irrigation network is recorded at distribution points.", "a": "adb8f8f96558dabd3949"}, {"screen": "dispatch", "text": "The volume delivered to water users is calculated across the on-farm network.", "a": "71ddcb7c509ce1622b3f"}, {"screen": "balance", "text": "IMIS calculates losses as the difference between supplied and delivered water to determine canal efficiency.", "a": "421d59e375f84f51d9cb"}]}, "what is a water limit?": {"answer": "A water limit is the authorized volume of water intake from a source, such as a river, set by the state environmental authority for a specific basin or region per quarter. It acts as a ceiling for water extraction rather than a limit on individual consumption. When this limit is exceeded, the system notifies the relevant organization and its superior, though water delivery to fields is not cut off.", "screen": "balance", "a": "35178685252ff9694213", "steps": []}, "how are violations recorded?": {"answer": "Violations are identified through on-site inspections or satellite monitoring and recorded via formal acts in the mobile app.", "screen": "satellite", "a": "10140d9e003a4634fecd", "steps": [{"screen": "satellite", "text": "A violation is detected directly by a field inspector or flagged automatically by Sentinel-2 satellite crop comparisons.", "a": "e1d08062900b3372b036"}, {"screen": "satellite", "text": "The inspector creates a violation act in the mobile app, attaching supporting photos, GPS coordinates, and the exact timestamp.", "a": "70c0c19fd1a24c4fc582"}, {"screen": "satellite", "text": "IMIS notifies the relevant WUA, and the supervisory department reviews the submitted act.", "a": "7ae86ab18be49886d54d"}, {"screen": "satellite", "text": "Upon final decision, the act is marked as closed and becomes irreversible.", "a": "b02de21a7b2bdcf178ba"}]}, "can a farmer have plots in two associations?": {"answer": "Yes, a farmer can have land located in the territories of two different Water User Associations. In this case, the farmer becomes a member of both WUAs and concludes a separate tripartite contract with each of them. However, the farmer receives a single personal account in IMIS, and each association only sees the plots registered within its own boundaries.", "screen": "users", "a": "b7fef7130912d0031cd6", "steps": []}, "how often are requests submitted?": {"answer": "Water requests in IMIS are submitted once every ten days (decade). A request is filed for a plot covered by an active contract, specifying the crop and sown area. Water users submit requests through the mobile app or website, or the WUA can submit on behalf of a farmer without a phone.", "screen": "contracts", "a": "f76ae6e2a65f7af51865", "steps": []}, "what is the role of a dispatcher?": {"answer": "In IMIS, a dispatcher is responsible for water distribution across canals within their organization and its subordinate levels. They monitor planned versus actual water delivery by ten-day periods (decades) and track operational water allocation. Following the visibility rule, a dispatcher sees the water distribution data of their own organization and everything beneath it.", "screen": "dispatch", "a": "e5d4a696b44624a9314f", "steps": []}, "what does an inspector do?": {"answer": "An inspector is responsible for field operations, including recording water readings at gauging stations, documenting violations, and completing assigned tasks like patrols or repairs. They use the mobile app to capture photos, GPS locations, and timestamps for all activities, ensuring data is accurately recorded in IMIS. Inspectors also verify compliance with contracts and assist in monitoring the irrigation network's condition.", "screen": "readings", "a": "9df6bb1a080b91fd256c", "steps": [{"screen": "readings", "text": "The inspector visits the gauging station and records the water level or flow using the mobile app.", "a": "89f01f1c7baee6687150"}, {"screen": "satellite", "text": "If a satellite check flags a potential issue, the inspector receives an assignment to visit the plot and verify the crop or area.", "a": "da89fecf65125bb2d590"}, {"screen": "complaints", "text": "The inspector carries out assigned tasks, such as investigating complaints or performing maintenance, and submits a report with photos and GPS data.", "a": "7851de115759f89c76b5"}, {"screen": "readings", "text": "Offline data, such as readings or violation reports, is automatically synced to IMIS once the inspector regains a network connection.", "a": "3d4d090e67719ee7a675"}]}, "what happens when a contract expires?": {"answer": "When a contract expires, it transitions to an 'expired' status, meaning no new water requests can be submitted under it. The contract itself is not deleted, as its history is preserved in the system. The water user must contact their WUA to initiate a renewal, which allows for updating conditions like area or crops while keeping the original contract number and history.", "screen": "contracts", "a": "7664cae2fc14a7e9672e", "steps": [{"screen": "contracts", "text": "The system notifies the water user and the WUA before the contract term ends.", "a": "98d4d0fbc9c018f9047b"}, {"screen": "contracts", "text": "The water user applies for renewal through the WUA, confirming their intent to continue.", "a": "f9bacacb155b0b1ad83a"}, {"screen": "contracts", "text": "The WUA updates the contract terms if necessary and extends the validity period.", "a": "ecfc86a0b35d87608075"}, {"screen": "contracts", "text": "The system retains the original contract number and history, allowing water requests to resume.", "a": "d76d452a5331f71658a6"}]}, "how is a plot registered?": {"answer": "A plot is registered by the Water User Association (WUA) after the farmer provides their passport, tax number (INN), and land certificate. The WUA enters these details into IMIS, which then automatically assigns a unique number and links the plot to the irrigation canal and hydromodule district based on the cadastral data.", "screen": "users", "a": "79001582ef8ede7f6cfc", "steps": [{"screen": "users", "text": "The farmer submits their passport, tax number, and land certificate to the WUA.", "a": "a313663ecf14a23d1917"}, {"screen": "users", "text": "The WUA employee enters the cadastral number and area into IMIS.", "a": "fb09446bb60de5a67847"}, {"screen": "users", "text": "IMIS automatically assigns a unique number and determines the canal and hydromodule district.", "a": "cc5e60a6c12e7bc773e3"}, {"screen": "map", "text": "The plot's boundaries are drawn on the map using GPS survey data.", "a": "dce331f1ef6978bbc45f"}]}, "how are plot boundaries drawn?": {"answer": "Plot boundaries in IMIS are drawn on the interactive map layer based on field GPS survey data collected along the plot perimeter. If a field survey has not been conducted yet, the boundary can be manually traced on the map as an approximation or marked with a temporary point.", "screen": "users", "a": "f2fcabf6b8d7ecc12da6", "steps": [{"screen": "users", "text": "Perform a field GPS survey by recording coordinates while walking along the perimeter of the plot.", "a": "50c65b5a9d2a900adada"}, {"screen": "map", "text": "Import or draw the recorded GPS coordinates onto the IMIS map layer to create the precise plot outline.", "a": "36acd8880fb2e2b3445d"}, {"screen": "users", "text": "If a GPS survey is unavailable, manually trace the boundary on the map for visual reference.", "a": "32e79d2cad49929eaa59"}, {"screen": "contracts", "text": "Ensure that the outline's calculated area does not exceed the registered contract area.", "a": "81fd23664df250428e7c"}]}, "what is the difference between net and gross norm?": {"answer": "In IMIS, irrigation norms are determined for each ten-day period based on the crop and hydromodule district using the FAO / CROPWAT methodology. The net norm is the exact volume of water needed directly by the crop for proper plant growth. The gross norm is the total volume of water that must be withdrawn from the source to deliver that required net volume to the field. It is calculated by dividing the net norm by the efficiency coefficient of the canal network to account for conveyance losses.", "screen": "norms", "a": "00e661050e6e7eaa5d85", "steps": []}, "what is canal efficiency?": {"answer": "Canal efficiency is the ratio of the volume of water delivered to water users to the volume of water supplied to the network. It is calculated per canal and per organization to identify where seepage, evaporation, or unaccounted intake losses are highest, helping to prioritize repairs.", "screen": "balance", "a": "c612a3d3a569750093c0", "steps": []}, "what is a ten-day summary?": {"answer": "A ten-day summary is a report where each organization submits data on water delivery, charges, payments, and debt to the organization directly above it in the hierarchy. The superior organization then reviews and accepts these summaries to ensure accurate reporting and water accounting. This process is a key part of the dispatching and reporting cycle in IMIS.", "screen": "dispatch", "a": "5914d818c2f5aa59048b", "steps": []}, "how are permissions managed?": {"answer": "Permissions in IMIS are managed by assigning specific rights to each position, where every menu item and action is represented by a checkbox. Administrators can grant additional individual rights to a person, such as during substitution, which override standard role settings. Business parameters like tariffs and thresholds are configured in the admin panel rather than through code changes.", "screen": "admin", "a": "e55d71c354dd06c713df", "steps": [{"screen": "admin", "text": "The administrator assigns a standard set of permissions to each position based on its role.", "a": "6ca3863bf26e1142f33a"}, {"screen": "admin", "text": "Individual rights can be granted to specific employees to allow for substitution or special tasks.", "a": "6e67a2f673068b5c981e"}, {"screen": "admin", "text": "Business parameters are updated directly in the admin panel to reflect current rules without modifying the system code.", "a": "3cf58abc5e009a4adeb2"}]}, "can a user get extra rights?": {"answer": "Yes, a user can receive additional permissions beyond those provided by their standard role or position. Management can assign individual rights directly to a specific employee, such as when they are temporarily substituting for another person. Every permission is managed as an individual checkbox in the system settings without needing code modifications.", "screen": "admin", "a": "bb5947d75ae33b7750fd", "steps": []}, "what is the audit log?": {"answer": "In IMIS, the audit log records every action taken in the system, capturing who made the change, what was changed (including old and new values), when, and from where, including external bank requests. It is strictly append-only, meaning no entries can ever be edited or deleted by anyone, not even a system administrator.", "screen": "reports", "a": "d22a2329cc17d2693cf5", "steps": []}, "can anyone delete the audit log?": {"answer": "No, nobody can edit or delete the audit log in IMIS, not even the system administrator. The audit log is strictly append-only to ensure complete security, accountability, and an unalterable record of all system actions.", "screen": "reports", "a": "fe49c92bdb3b80065daf", "steps": []}, "how does the map work?": {"answer": "The IMIS map is a dynamic tool that integrates GIS layers with system data to visualize the irrigation infrastructure and water usage. It displays rivers, canals, gauging stations, and plots, allowing users to switch layers on or off and color-code plots by crop or payment status. You can open a plot directly from the map to view its details, while the satellite layer helps compare vegetation indices with declared crops to identify potential issues.", "screen": "map", "a": "e5d1660223e4439c1246", "steps": [{"screen": "map", "text": "The map overlays IMIS data like plots and canals onto base layers from the GIS server.", "a": "cc4f24677d7c93227b60"}, {"screen": "map", "text": "Users can toggle specific layers to view infrastructure or color-code plots based on crops or payment status.", "a": "84fafc4a6e3c2affadcb"}, {"screen": "map", "text": "Clicking on a plot or object on the map opens its specific details and history.", "a": "003a38ad8ef1ea28f25c"}, {"screen": "satellite", "text": "The satellite layer allows for visual comparison of vegetation indices against declared crop data.", "a": "4d0c6d83aeda35baebf0"}]}, "which layers are on the map?": {"answer": "IMIS maps display base GIS layers from GeoServer, such as rivers, reservoirs, drainage networks, administrative districts, and settlements. Operational IMIS layers include land plots, canals, gauging stations, pump stations, WUA territories, and WUA sensors. You can easily switch these layers on or off, view plots color-coded by crop, or click a plot to open its detailed information directly from the map.", "screen": "map", "a": "7fc6857ca2cc7c4cbf38", "steps": []}, "what is ndvi?": {"answer": "NDVI is the Normalized Difference Vegetation Index, which IMIS uses to monitor the vegetation health of a plot. The system compares the satellite-derived NDVI of a plot with the reference value for the declared crop in that ten-day period. A mismatch does not trigger a penalty but serves as a reason to send an inspector to verify the situation on the ground.", "screen": "satellite", "a": "9940fb5b170ab47070c5", "steps": []}, "what happens if the satellite shows a different crop?": {"answer": "If satellite data shows a mismatch with the declared crop or area, IMIS does not issue an automatic penalty. Instead, it flags the plot as a reason to send an inspector to verify the situation on the ground. The inspector then records the actual findings with a photo and GPS location to resolve the discrepancy.", "screen": "satellite", "a": "299fc918234786f04986", "steps": [{"screen": "satellite", "text": "IMIS compares the vegetation index (NDVI) of the plot with the reference for the declared crop.", "a": "d79058c3cbbf3e9c1544"}, {"screen": "satellite", "text": "A mismatch triggers an automated notification and creates an assignment for an inspector.", "a": "912abd6dc5dde6ee8742"}, {"screen": "complaints", "text": "The inspector visits the plot to verify the crop and records the findings with a photo and GPS.", "a": "b541b34b09799e8b5cf3"}, {"screen": "satellite", "text": "The higher department reviews the inspector's report to finalize the status of the plot.", "a": "b9ece28a75c3bf4435b2"}]}, "how are complaints answered?": {"answer": "Complaints are managed through the mobile app and handled by the organization directly above the WUA to ensure impartial review. The process involves assigning a responsible person, investigating the cause, and recording the final resolution, which the farmer can then view in their profile.", "screen": "complaints", "a": "31319b43510999c6005e", "steps": [{"screen": "complaints", "text": "The farmer submits a complaint via the mobile app, attaching a photo and specifying the relevant plot and water request.", "a": "40cd64722dbd06bd7c90"}, {"screen": "complaints", "text": "The complaint is registered and automatically routed to the organization above the WUA, where a responsible employee is assigned.", "a": "a189814fcf9c8e38344d"}, {"screen": "complaints", "text": "The assigned employee investigates the cause, such as infrastructure damage or water delivery issues, and records the resolution in the system.", "a": "325ebc771b8927c09540"}, {"screen": "complaints", "text": "Once resolved, the answer and date are saved, allowing the farmer to view the status and response directly in their app profile.", "a": "a6800c3732b2795ff83a"}]}, "what is an assignment?": {"answer": "An assignment is a task issued by a higher-level organization to an inspector, such as performing an inspection, patrol, maintenance, or recording readings. These tasks are generated based on work plans, complaints, satellite mismatches, or incidents, and they include a priority level and a deadline. The inspector completes the assignment by submitting a report with a photo and GPS location, and overdue assignments remain open in the system.", "screen": "complaints", "a": "eb2eb9a58d86970c98f7", "steps": [{"screen": "complaints", "text": "A higher-level organization creates an assignment for an inspector based on a specific trigger like a complaint or satellite mismatch.", "a": "885a8af83f8514ab7e0b"}, {"screen": "complaints", "text": "The inspector receives the assignment in the mobile app and travels to the specified object to perform the work.", "a": "d4edc22565eef3ef3a07"}, {"screen": "complaints", "text": "The inspector records the results, attaches a photo, and marks the assignment as complete.", "a": "738b10483a1f35b6de98"}]}, "how is the membership fee charged?": {"answer": "The WUA membership fee is managed separately from water charges within IMIS. It is set by the WUA itself and is not calculated based on water volume or the standard water tariff.", "screen": "billing", "a": "efd9926e4c7788261996", "steps": []}, "what is recalculation?": {"answer": "Recalculation is a specific operation performed by the Agency of Melioration and Irrigation (AMI) to adjust charges when underlying parameters, such as tariffs or norms, change after a period has already been closed. Since past records are never deleted or overwritten, a recalculation creates a corrective charge to account for the difference. This ensures that financial records remain consistent with bank and accounting systems while maintaining a clear audit trail of all adjustments.", "screen": "billing", "a": "0ee9484ed4ec04578cbf", "steps": [{"screen": "billing", "text": "Identify the closed period where parameters like tariffs or norms have changed.", "a": "f3ca528b12dcfbffc2c6"}, {"screen": "billing", "text": "AMI initiates the recalculation operation for the specified period.", "a": "63f8576ccc383583f6b8"}, {"screen": "billing", "text": "The system generates a corrective charge representing the difference between the original and the new calculated amount.", "a": "02a5e2200d9c32d9a1a5"}, {"screen": "reports", "text": "The adjustment is recorded in the audit log, linking the new charge to the original transaction.", "a": "1615ea6d65c94da869cc"}]}, "how does imis exchange data with 1c?": {"answer": "IMIS exchanges financial data with 1C through a dedicated gateway, where the accounting system requests charges for a specific period and IMIS provides the list of unexported records. Each record is marked as exported with a date and user, and the accounting system returns a document number and date to confirm the record is reconciled. This process ensures that financial data is synchronized without duplication, and any errors are corrected by reversal entries rather than deletion.", "screen": "billing", "a": "fb9b75568e6f5ffe57fe", "steps": [{"screen": "billing", "text": "The accounting system requests unexported charges for a specific period from IMIS.", "a": "dc7880970fa87ca92f9d"}, {"screen": "billing", "text": "IMIS sends the list of charges, including the taxpayer ID, organization, volume, tariff, and amount.", "a": "a11bf9494ad1285ee8da"}, {"screen": "billing", "text": "The accounting system returns the document number and date for each record to confirm it has been processed.", "a": "24fee93fd3db29258567"}, {"screen": "billing", "text": "IMIS saves these references, marking the charges as reconciled and preventing duplicate exports.", "a": "20fc20444b096e8b55d6"}]}, "what assets are tracked?": {"answer": "IMIS tracks various assets including pump stations, hydraulic structures, canal sections, drainage systems, and equipment. For each asset, the system maintains technical specifications, balance value, wear, current condition, and a history of inspections and maintenance.", "screen": "assets", "a": "1ebac6b4a0ec2455d68f", "steps": []}, "what are directories used for?": {"answer": "Directories in IMIS store essential reference data such as crops, irrigation norms, tariffs, hydromodule districts, and asset types. They are designed so that adding new items or updating values does not require system code changes, ensuring that historical calculations remain based on the data valid at that time.", "screen": "assets", "a": "2d56c8fa00ad361e2dd8", "steps": []}, "which reports can i get?": {"answer": "IMIS provides a wide range of reports covering water use, financial data, and control activities. You can generate reports by ten-day period, month, quarter, or year, which can be viewed on screen, exported to Excel, or printed. These reports are always consistent with the data of your organization and its subordinates.", "screen": "reports", "a": "f247d62c1209679f6dce", "steps": []}, "which languages does imis support?": {"answer": "IMIS supports three languages: Tajik, Russian, and English.", "screen": "intro", "a": "c976b1f88be4418cbc6b", "steps": []}, "who are the users of imis?": {"answer": "IMIS is designed for a wide range of users, including the Agency of Melioration and Irrigation (AMI), state departments like GUMI and BUMI, hydrographic sections (GGEU), water user associations (WUA), inspectors, dispatchers, financiers, and farmers. Each user role has a specific visibility level, ensuring that individuals only access data relevant to their organization and those below it in the hierarchy.", "screen": "orgs", "a": "dbcf5ca9a18b680bd254", "steps": []}, "how is the organization structure set up?": {"answer": "The organizational structure of IMIS is built on a simple hierarchy where each organization stores only the reference to its superior. This design allows the administrator to easily move any branch or level within the hierarchy without needing to reconfigure the rest of the system. The structure is defined by the reporting lines between AMI, state departments, basin departments, hydrographic sections, and water user associations.", "screen": "orgs", "a": "62790c69b5dac50ec7e5", "steps": [{"screen": "orgs", "text": "Define the superior organization for each entity in the system.", "a": "242b430e595c36204798"}, {"screen": "orgs", "text": "The system automatically builds the hierarchy based on these individual reporting links.", "a": "83391a4c3fea6c6309aa"}, {"screen": "orgs", "text": "Update the superior reference if a structural change is required, and the system will reflect the new hierarchy immediately.", "a": "f43bc99de77937a389a0"}]}, "can the hierarchy be changed?": {"answer": "Yes, the hierarchy can be changed by the administrator. Each organization stores only the reference to its superior, so any level can be moved without needing to rebuild the rest of the structure.", "screen": "orgs", "a": "bc3877e6a8b29bc91b10", "steps": [{"screen": "orgs", "text": "The administrator accesses the organization tree.", "a": "55a35671eb79672c5c06"}, {"screen": "orgs", "text": "The superior level for a specific organization is updated.", "a": "e8617df896cfe9173ab7"}, {"screen": "orgs", "text": "The system automatically updates the hierarchy based on the new link.", "a": "608c89688c6e2057ab50"}]}, "what is crop rotation used for?": {"answer": "Crop rotation in IMIS is used to define the list of crops and their sown areas for the upcoming year for each WUA. This data is essential for calculating the total yearly water demand, which is then aggregated through the departments to the national level. It serves as the foundation for planning water distribution before the season begins.", "screen": "norms", "a": "ce283a9b0239c9d70f8b", "steps": []}, "what happens if the water limit is exceeded?": {"answer": "When the water intake limit is exceeded, IMIS notifies the organization responsible for the intake and its superior department. However, water delivery to the fields is not cut off, as the system prioritizes the continuation of irrigation. The excess intake serves as a basis for investigation and water redistribution rather than immediate stoppage.", "screen": "balance", "a": "b550d543a0bdce985e38", "steps": []}, "can a farmer pay more than he owes?": {"answer": "No, a farmer cannot pay more than he owes. IMIS does not allow prepayment, and the bank cannot process payments exceeding the amount due on the personal account.", "screen": "billing", "a": "fa049ae73dc4071d4573", "steps": []}, "can a payment be reversed?": {"answer": "Yes, a payment can be reversed in IMIS. A mistake is corrected by a counter-entry, which ensures the record is never deleted, maintaining the integrity of the financial history.", "screen": "billing", "a": "37f223c1d8df71fc3374", "steps": [{"screen": "billing", "text": "Identify the incorrect payment record in the system.", "a": "535d0db7964fd4386fdf"}, {"screen": "billing", "text": "Execute a counter-entry to reverse the erroneous transaction.", "a": "9cfed0f39e2149fedb29"}, {"screen": "reports", "text": "Verify that the reversal is recorded in the audit log without deleting the original entry.", "a": "4171856d2db3e37e56cf"}]}, "how does imis protect data?": {"answer": "IMIS protects data through a strict role-based visibility rule, where users only see data for their own organization and those below it. Every action is recorded in an append-only audit log that cannot be edited or deleted, even by the administrator, ensuring full accountability. Additionally, all electronic documents are stored in a centralized database with access restricted by role.", "screen": "reports", "a": "839a8b733e39836416a9", "steps": [{"screen": "orgs", "text": "The system enforces a visibility rule where users only access data belonging to their organization and its subordinates.", "a": "54295402cb16075924b6"}, {"screen": "reports", "text": "Every change is recorded in an append-only audit log that tracks who performed the action, what was changed, and when.", "a": "c4ced4c04fded53751c2"}, {"screen": "admin", "text": "Permissions are managed through specific roles, and the administrator cannot alter or delete the audit log entries.", "a": "fa32e3a0be3842071d56"}]}, "can a farmer see other farmers' data?": {"answer": "No, a farmer cannot see other farmers' data. According to the IMIS visibility rules, a farmer is restricted to viewing only their own plots, contracts, water requests, bills, and payments. Access to data is strictly limited to the organization the user belongs to and everything below it in the hierarchy.", "screen": "users", "a": "a99a84bdc87feb36bcfd", "steps": []}, "how are gauging stations connected?": {"answer": "Gauging stations are connected to a specific organization and a water object, such as a canal or river, to ensure accurate water accounting. These stations are linked to the organization responsible for their maintenance and the water object where the measurements are taken, allowing data to be integrated into the system's water balance and distribution reports.", "screen": "links", "a": "dcbc3a5036bcf88a776b", "steps": [{"screen": "links", "text": "A gauging station is registered in the system and assigned to a specific organization.", "a": "e3abfc812ccf5294c1ff"}, {"screen": "links", "text": "The station is then linked to the corresponding water object, such as a main or distribution canal.", "a": "5864ebebb9b00972f259"}, {"screen": "readings", "text": "Once connected, the station is used by inspectors to record water levels or flow rates, which are then processed for water accounting.", "a": "3a6060d3782df0851fde"}]}, "what is a rating curve?": {"answer": "A rating curve is a mathematical formula or table used in IMIS to convert the measured water level at a gauging station into a flow rate in cubic meters per second. This conversion is essential for accurate water accounting, as it allows the system to calculate the volume of water passing through a specific point based on the height of the water surface. These curves can be imported into IMIS from Excel files to ensure precise flow monitoring.", "screen": "readings", "a": "aeed68e99413db7bb347", "steps": []}, "can sensors send data automatically?": {"answer": "Yes, IMIS is designed to receive data automatically from level sensors and flow meters via its telemetry API. While the system supports this automated data collection, currently, readings are entered manually by inspectors in the mobile app until telemetry infrastructure is fully installed.", "screen": "readings", "a": "821d299c6f0d19873dc7", "steps": [{"screen": "readings", "text": "Sensors transmit data via the telemetry API to the IMIS database.", "a": "d4223eef5635a9a388b2"}, {"screen": "readings", "text": "The system validates the incoming data for consistency and stores it.", "a": "3265a982ed3405bddcd1"}, {"screen": "balance", "text": "Validated readings are then used for water balance calculations and plan comparisons.", "a": "3b548d50b1caad6247f8"}]}, "how does a farmer file a complaint?": {"answer": "A farmer files a complaint through the mobile app, indicating the plot, the request, and describing the issue with a photo.", "screen": "complaints", "a": "710585960c1e72ca5f4a", "steps": [{"screen": "complaints", "text": "Open the mobile app and navigate to the profile or complaint section.", "a": "1504380d973fd8e48f07"}, {"screen": "complaints", "text": "Select the relevant plot and request where the issue occurred.", "a": "d462a3442efd04180401"}, {"screen": "complaints", "text": "Choose the type of issue, add a description and a photo, and submit the complaint.", "a": "60baf7162463a82da946"}]}, "what does a farmer see in the app?": {"answer": "In the mobile app, a farmer sees only their own plots, contracts, bills, and complaints.", "screen": "users", "a": "f2dd3c2e4ec8084b7e07", "steps": [{"screen": "users", "text": "The farmer logs into the mobile app and accesses their personal profile.", "a": "df5ca7aa944c48cc20de"}, {"screen": "contracts", "text": "They view their active contracts and submit water requests for their plots.", "a": "a20245569701ce7d84fa"}, {"screen": "billing", "text": "They check their personal account balance, review bills, and file complaints if needed.", "a": "f3accdb08bdb13364dc3"}]}, "hello": {"answer": "I am the assistant for IMIS, the Irrigation Management Information System of the Agency of Melioration and Irrigation (AMI) of Tajikistan. IMIS manages organizational structures, water objects, farmer contracts, water requests, delivery monitoring, and automated billing. Please ask a specific question about contracts, water requests, payments, or any other system feature.", "screen": "intro", "a": "61bd83fba2754c1a5cd5", "steps": []}, "can a water user association change the tariff?": {"answer": "No, a water user association cannot change the water tariff. The water tariff is set centrally by the state antimonopoly authority (5 dirams per cubic meter) and updated in IMIS at the Agency level. A WUA is only authorized to establish its own separate membership fee.", "screen": "billing", "a": "255873b31355824fb9df", "steps": []}, "can a wua set its own membership fee?": {"answer": "Yes, each Water User Association sets its own membership fee amount. In IMIS, membership fees are tracked and accounted for separately from water delivery charges.", "screen": "billing", "a": "a07b9f4f59a05552ba37", "steps": []}, "who can see the audit log?": {"answer": "The audit log is accessible only to AMI (the Agency of Melioration and Irrigation) and the system administrator. It records all system activities, including user details, changes made, timestamps, and access logs. To ensure security and compliance, these records are append-only and cannot be edited or deleted by anyone, including the administrator.", "screen": "reports", "a": "3a5442bef71b2b777912", "steps": []}, "hello can you tell me about the building": {"answer": "In IMIS, physical structures and assets of the irrigation network—such as hydraulic structures, pump stations, canal sections, and drainage systems—are registered and tracked in the Assets section. The system stores technical and financial details including capacity, balance value, wear level, physical condition, and assigned organization. It also manages inspection dates with automated reminders and records repair histories to help prioritize maintenance where water losses are highest.", "screen": "assets", "a": "aa589524b4082cd1e106", "steps": []}, "can a farmer change the crop after the request is approved?": {"answer": "Once a water request is approved, the crop and sown area are fixed for that ten-day period to ensure accurate water scheduling. If a farmer needs to change the crop, they must wait for the next ten-day period to submit a new request. The system validates the area against the contract and the approved plan to maintain consistency in water distribution.", "screen": "contracts", "a": "8dfeb2d294b5fdf7ba2f", "steps": [{"screen": "contracts", "text": "Wait for the current ten-day period to conclude.", "a": "fb655ddac4f7763a62bb"}, {"screen": "contracts", "text": "Submit a new water request for the next decade with the updated crop details.", "a": "b3cb4a72f4ff43f7f1be"}, {"screen": "contracts", "text": "Ensure the new request complies with the contract area and crop rotation plan.", "a": "59019398d569f6510649"}]}, "who approves a water request?": {"answer": "Water requests are approved or rejected by the Water User Association (WUA) or a department directly above it, depending on whoever holds the 'requests: approve' permission in IMIS. Once approved, the request is placed into the water distribution schedule. Approval does not generate any charges, as billing occurs strictly after the actual delivery is recorded in an acceptance act.", "screen": "contracts", "a": "63100814787910e8ed8d", "steps": []}, "how are tariffs changed?": {"answer": "Tariffs are managed in the admin panel by adding a new rate along with its effective start date, ensuring previous bills remain untouched.", "screen": "billing", "a": "49d18e8f276a6ada272c", "steps": [{"screen": "billing", "text": "An administrator adds a new tariff record with its effective start date in the admin panel.", "a": "44b069963b90b7c391cf"}, {"screen": "billing", "text": "Previously calculated charges retain their original tariff rate and are never retroactively altered.", "a": "dce337e1a92e89d5e85e"}, {"screen": "billing", "text": "All new water deliveries starting on or after the start date automatically calculate charges using the updated tariff.", "a": "35d1042a55c7cf002ab4"}]}, "who signs the contract?": {"answer": "A water service contract in IMIS is a tripartite agreement involving three parties: the water user (farmer), the Water User Association (WUA), and the superior department directly above the WUA (GUMI, BUMI, or GGEU). The farmer signs the physical document, and the higher department confirms it to finalize the contract in IMIS. Once signed by all parties, a scan of the contract is uploaded into the system.", "screen": "contracts", "a": "eb77d1a854824ba7c482", "steps": []}, "who can create a new organization?": {"answer": "Only the administrator of IMIS has the authority to create a new organization within the system. The administrator manages the organizational hierarchy and can define the reporting structure by assigning a superior organization to each new entry.", "screen": "admin", "a": "ccb324746f88f3ff8ec8", "steps": []}, "can you tell me about the meeting": {"answer": "I am the IMIS assistant, and I can only help you with questions related to the Irrigation Management Information System, including water management, contracts, billing, and reports. If you would like to know how IMIS operates or need help with a specific section, please feel free to ask.", "screen": "intro", "a": "9470deea2cac1db723f2", "steps": []}, "information system": {"answer": "IMIS is the Irrigation Management Information System of the Agency of Melioration and Irrigation of the Republic of Tajikistan, designed for comprehensive water resources management, planning, and accounting. It supports multi-level organizational structures, interactive mapping, billing, and monitoring of water delivery across the country in Tajik, Russian, and English. You can ask about a specific section such as water users, contracts, water requests, or billing.", "screen": "intro", "a": "6514c9a4e15af4c33da2", "steps": []}};
window.INTENTS=[{"re": "основн\\w* (раздел|меню)|раздел\\w* основн|\\bmain (section|menu)", "screen": "map", "ans": "The Main section has two items: the Dashboard — the key figures of your organisation and its tree, water, money and open tasks — and the Map with canals, hydroposts and plots as layers.", "ans_ru": "В разделе «Основное» два пункта. Дашборд — главные цифры вашей организации и всех, кто под ней: вода, деньги, открытые задачи. И Карта — каналы, гидропосты и участки отдельными слоями.", "a": "2df66668d7268fda9c93", "a_ru": "134ae1e80664dbb8410a", "srazu": true, "nado": "раздел|меню|section|menu|наход|входит|что в |что есть|what.?s in|what is in|under|под "}, {"re": "водопользовани|water[- ]use (section|menu)", "screen": "norms", "ans": "Water use holds the water planning work: plots, water requests, hydromodule districts, the water use plan by ten-day periods, crop rotation, water limits, the water balance, dispatching — planned versus actual delivery — and canal efficiency.", "ans_ru": "В разделе «Водопользование» — вся работа с водой: участки, заявки на воду, гидромодульные районы, план водопользования по декадам, севооборот, лимиты воды, баланс воды, диспетчеризация — план и факт подачи — и эффективность каналов.", "a": "43858da9fa03b14dbab8", "a_ru": "81976c68d015f7501bb4", "srazu": true, "nado": "раздел|меню|section|menu|наход|входит|что в |что есть|what.?s in|what is in|under|под "}, {"re": "уч[её]т\\w* и контрол|accounting and control|control section", "screen": "readings", "ans": "Accounting and control covers measurement and field control: readings, hydroposts, rating curves of the posts, violations, complaints and assignments for inspectors.", "ans_ru": "В разделе «Учёт и контроль» — замеры и контроль на месте: показания, гидропосты, тарировка постов, нарушения, жалобы и задания инспекторам.", "a": "e425ea5e8e5e7866368a", "a_ru": "2ec2fb83b376a9b4bfc6", "srazu": true, "nado": "раздел|меню|section|menu|наход|входит|что в |что есть|what.?s in|what is in|under|под "}, {"re": "финанс|finance", "screen": "billing", "ans": "Finance holds the money side: contracts with water users, payments through the bank, billing and export to 1C, recalculation of charges, and the membership fee of the water user association.", "ans_ru": "В разделе «Финансы» — всё о деньгах: договоры с водопользователями, платежи через банк, биллинг и выгрузка в 1С, перерасчёт начислений и членский взнос АВП.", "a": "12cb907eb25126ce919d", "a_ru": "99540bcac093336ecc32", "srazu": true, "nado": "раздел|меню|section|menu|наход|входит|что в |что есть|what.?s in|what is in|under|под "}, {"re": "реестр|registr(y|ies)\\b", "screen": "users", "ans": "Registries keep the base records: the register of water users, the organisation structure from the Agency down to the associations, the directories — crops, tariffs, norms — and the AFMS register of assets: canals, gates and pumping stations.", "ans_ru": "В разделе «Реестры» — основные записи системы: реестр водопользователей, структура организаций от Агентства до ассоциаций, справочники — культуры, тарифы, нормы — и реестр активов AFMS: каналы, затворы, насосные станции.", "a": "f0908adb3a7a77c4712d", "a_ru": "62eea08445a03215a47f", "srazu": true, "nado": "раздел|меню|section|menu|наход|входит|что в |что есть|what.?s in|what is in|under|под "}, {"re": "аналитик|analytics", "screen": "reports", "ans": "Analytics has three items: KPI — the key indicators by organisation; Reports — by ten-day period, month, quarter and year, with export to Excel and PDF; and ten-day summaries, which the organisations submit and the higher level accepts.", "ans_ru": "В разделе «Аналитика» три пункта. KPI — главные показатели по организациям. Отчёты — за декаду, месяц, квартал и год, с выгрузкой в Excel и PDF. И декадные сводки, которые организации сдают, а вышестоящая принимает.", "a": "a8ed1acb0e7fcbfd2f16", "a_ru": "c3a39108ee7a5d149979", "srazu": true, "nado": "раздел|меню|section|menu|наход|входит|что в |что есть|what.?s in|what is in|under|под "}, {"re": "администрировани|administration|admin (section|menu)", "screen": "admin", "ans": "Administration is for the administrator: users and their rights, organisations and water objects, the audit log of every change, and staff.", "ans_ru": "Раздел «Администрирование» — для администратора: пользователи и их права, организации и водные объекты, журнал аудита всех изменений и сотрудники.", "a": "d0b1c4df26112ee0927b", "a_ru": "1972cc013959a1770509", "srazu": true, "nado": "раздел|меню|section|menu|наход|входит|что в |что есть|what.?s in|what is in|under|под "}, {"re": "меню|\\bmenu\\b|(кажд\\w*|все\\w*)\\s+раздел|(each|every|all)\\s+(of the\\s+)?(menu\\s+)?sections?", "screen": "intro", "ans": "The IMIS menu has seven sections. Each person sees only the items their rights allow.", "ans_ru": "Меню системы делится на семь разделов. Каждый видит только те пункты, на которые у него есть права.", "a": "2eeb0d3f96f2c656acab", "a_ru": "e90a1f73e55ef3c163fc", "srazu": true, "steps": [{"screen": "map", "text": "The Main section has two items: the Dashboard — the key figures of your organisation and its tree, water, money and open tasks — and the Map with canals, hydroposts and plots as layers."}, {"screen": "norms", "text": "Water use holds the water planning work: plots, water requests, hydromodule districts, the water use plan by ten-day periods, crop rotation, water limits, the water balance, dispatching — planned versus actual delivery — and canal efficiency."}, {"screen": "readings", "text": "Accounting and control covers measurement and field control: readings, hydroposts, rating curves of the posts, violations, complaints and assignments for inspectors."}, {"screen": "billing", "text": "Finance holds the money side: contracts with water users, payments through the bank, billing and export to 1C, recalculation of charges, and the membership fee of the water user association."}, {"screen": "users", "text": "Registries keep the base records: the register of water users, the organisation structure from the Agency down to the associations, the directories — crops, tariffs, norms — and the AFMS register of assets: canals, gates and pumping stations."}, {"screen": "reports", "text": "Analytics has three items: KPI — the key indicators by organisation; Reports — by ten-day period, month, quarter and year, with export to Excel and PDF; and ten-day summaries, which the organisations submit and the higher level accepts."}, {"screen": "admin", "text": "Administration is for the administrator: users and their rights, organisations and water objects, the audit log of every change, and staff."}], "steps_ru": [{"screen": "map", "text": "В разделе «Основное» два пункта. Дашборд — главные цифры вашей организации и всех, кто под ней: вода, деньги, открытые задачи. И Карта — каналы, гидропосты и участки отдельными слоями."}, {"screen": "norms", "text": "В разделе «Водопользование» — вся работа с водой: участки, заявки на воду, гидромодульные районы, план водопользования по декадам, севооборот, лимиты воды, баланс воды, диспетчеризация — план и факт подачи — и эффективность каналов."}, {"screen": "readings", "text": "В разделе «Учёт и контроль» — замеры и контроль на месте: показания, гидропосты, тарировка постов, нарушения, жалобы и задания инспекторам."}, {"screen": "billing", "text": "В разделе «Финансы» — всё о деньгах: договоры с водопользователями, платежи через банк, биллинг и выгрузка в 1С, перерасчёт начислений и членский взнос АВП."}, {"screen": "users", "text": "В разделе «Реестры» — основные записи системы: реестр водопользователей, структура организаций от Агентства до ассоциаций, справочники — культуры, тарифы, нормы — и реестр активов AFMS: каналы, затворы, насосные станции."}, {"screen": "reports", "text": "В разделе «Аналитика» три пункта. KPI — главные показатели по организациям. Отчёты — за декаду, месяц, квартал и год, с выгрузкой в Excel и PDF. И декадные сводки, которые организации сдают, а вышестоящая принимает."}, {"screen": "admin", "text": "Раздел «Администрирование» — для администратора: пользователи и их права, организации и водные объекты, журнал аудита всех изменений и сотрудники."}]}, {"re": "pay|payment|bank|debt|owe|personal account|оплат|плат[её]ж|банк|долг|задолж|лицев", "screen": "billing", "ans": "In IMIS a charge is created only after the delivery act, from the actual volume of water times the approved tariff. The farmer pays through the bank by his personal account number: the bank sees his open bills, he chooses which one to pay, and the payment is booked automatically. Nobody can pay more than is owed, and a mistaken payment is reversed, never deleted.", "ans_ru": "В системе начисление появляется только после акта приёма воды: фактический объём умножается на утверждённый тариф. Водопользователь платит через банк по номеру лицевого счёта — банк видит его открытые счета, он выбирает, какой оплатить, и платёж разносится сам. Заплатить больше долга нельзя, а ошибочный платёж отменяется встречной записью и не удаляется.", "a_ru": "c6d952f63a3513886f60", "a": "3d9747ce3113f3b33437"}, {"re": "request|order water|apply|заявк|заказ", "screen": "contracts", "ans": "Every ten days the farmer requests water for a plot under his contract, giving the crop and the sown area — from the mobile app or the website. If he has no phone, the association submits it for him. The area is checked against the contract, and the association or the department above it approves the request. Nothing is charged at approval.", "ans_ru": "Раз в декаду водопользователь подаёт заявку на воду по участку из своего договора: культура и площадь посева — в мобильном приложении или на сайте. Если у него нет телефона, заявку подаёт ассоциация. Площадь сверяется с договором, а одобряет заявку ассоциация или вышестоящее управление. При одобрении ничего не начисляется.", "a_ru": "b4ae5365fbe2d27f518f", "a": "6db83a237ba6847e5aac"}, {"re": "contract|agreement|sign|договор|подпис", "screen": "contracts", "ans": "Water is supplied only under a contract between the water user, the water user association and the department directly above the association. The system assigns the number, the farmer signs it, and the higher department confirms it. Before the term ends both are reminded, and the contract is extended keeping its number and history.", "ans_ru": "Вода подаётся только по договору между водопользователем, ассоциацией и управлением, которому подчинена ассоциация. Номер присваивает система, водопользователь подписывает, вышестоящее управление подтверждает. Перед окончанием срока обоих извещают, и договор продлевается с сохранением номера и истории.", "a_ru": "5c2a838ac387e205e750", "a": "d26eacd6d74807d1aaf0"}, {"re": "hydromodule|norm|irrigation rate|net|gross|fao|гидромодул|норм", "screen": "norms", "ans": "Water norms depend on the land. IMIS keeps nine hydromodule districts, defined by groundwater depth and soil: where groundwater is close, roots get moisture from below and need less water. For every crop in every district there is a net and a gross norm for each ten-day period, by the FAO methodology. Gross is net divided by the efficiency of the network.", "ans_ru": "Норма полива зависит от земли. В системе девять гидромодульных районов — по глубине грунтовых вод и составу почвы: где грунтовые воды близко, корням нужно меньше воды. Для каждой культуры в каждом районе заданы нормы нетто и брутто по декадам, по методике ФАО. Брутто — это нетто, делённое на КПД сети.", "a_ru": "fca3d9e50d77d9d4454e", "a": "734c88b7a7515ad4bc41"}, {"re": "plan|crop rotation|season|decade|ten-day|план|севооборот|декад", "screen": "norms", "ans": "Before the season each association enters its crop rotation. From crops, areas and norms IMIS builds the water use plan — plot by plot, for all thirty-six ten-day periods of the year — and the needs add up from the association to the national level.", "ans_ru": "До начала сезона каждая ассоциация вносит севооборот. Из культур, площадей и норм система строит план водопользования — по каждому участку, на все тридцать шесть декад года, и потребности складываются от ассоциации до всей страны.", "a_ru": "f29a8b57bc5c01c19483", "a": "0051ef7b5963b5a982ae"}, {"re": "reading|meter|gaug|station|rating curve|level|flow|показан|гидропост|тарировк|расход", "screen": "readings", "ans": "Water is measured at gauging stations. An inspector enters the reading in the mobile app with a photo of the gauge, the GPS location and the time; without a signal it is saved and sent later. A rating curve turns the water level into flow, and the volume for the period is the difference from the previous reading.", "ans_ru": "Вода измеряется на гидропостах. Инспектор вносит показание в мобильном приложении с фотографией прибора, координатами и временем; без связи оно сохраняется и уходит позже. Тарировочная таблица переводит уровень воды в расход, а объём за период — это разница с прошлым показанием.", "a_ru": "e3d44972ce10bf9e600e", "a": "88fccef115fba4617e1f"}, {"re": "sensor|telemetr|automatic|датчик|телеметр", "screen": "readings", "ans": "IMIS is ready to receive data directly from level sensors and flow meters through its telemetry interface. Today readings are entered by inspectors in the mobile app, and both kinds of data are processed the same way.", "ans_ru": "Система готова принимать данные прямо с датчиков уровня и расходомеров через интерфейс телеметрии. Сейчас показания вносят инспекторы в мобильном приложении, и оба вида данных обрабатываются одинаково.", "a_ru": "26c49be96816f2dc9932", "a": "7afa92f7707d5b496827"}, {"re": "dispatch|ten-day summar|диспетчер|сводк", "screen": "dispatch", "ans": "Dispatchers follow the distribution of water across the canals ten-day period by ten-day period, planned against actual, so a shortfall shows up immediately. Every ten days each organization submits a summary to the one above, which accepts it.", "ans_ru": "Диспетчеры следят за распределением воды по каналам по декадам — план против факта, — поэтому недоподача видна сразу. Раз в декаду каждая организация сдаёт сводку вышестоящей, и та её принимает.", "a_ru": "402012f69e0f72742972", "a": "87b7d42b5757f2757dac"}, {"re": "limit|balance|loss|efficien|seepage|лимит|баланс|потер|кпд", "screen": "balance", "ans": "A limit is the volume the state allows to be taken from a river, by basin and quarter; IMIS warns when it is exceeded but never cuts water to the fields. The water balance compares water taken, supplied and delivered, and canal efficiency shows which canal loses the most water.", "ans_ru": "Лимит — это объём, который государство разрешает забрать из реки, по бассейну и кварталу. При превышении система извещает, но подачу воды на поля не прекращает. Баланс воды сравнивает забранное, поданное и доведённое, а КПД каналов показывает, где теряется больше всего воды.", "a_ru": "acc6c4512af0e65b31d3", "a": "17c6e25421265bc70602"}, {"re": "map|layer|gis|geoserver|карт|сло[йи]", "screen": "map", "ans": "The map is a working tool. Base layers come from the GIS server — rivers, reservoirs, drainage, districts and settlements — and IMIS adds its own: plots, canals, gauging stations, pump stations and association territories. Plots are coloured by crop and open straight from the map.", "ans_ru": "Карта — рабочий инструмент. Базовые слои приходят с ГИС-сервера: реки, водохранилища, дренаж, районы и населённые пункты. Поверх система рисует свои: участки, каналы, гидропосты, насосные станции и территории ассоциаций. Участки окрашены по культурам и открываются прямо с карты.", "a_ru": "5c086cd799a757a98adb", "a": "f4f3d47f2a3f7eaa8836"}, {"re": "satellite|sentinel|ndvi|спутник|снимок", "screen": "satellite", "ans": "IMIS checks plots with Sentinel-2 satellite images. It shows the true-colour image and the vegetation index of the plot with its outline, and compares the index with the reference for the declared crop. A mismatch is not a penalty — it is a reason to send an inspector.", "ans_ru": "Система проверяет участки по снимкам спутника Sentinel-2. Показывается снимок участка в обычном цвете и индекс растительности с контуром участка, и индекс сравнивается с эталоном для заявленной культуры. Несовпадение — не штраф, а повод отправить инспектора.", "a_ru": "1695244bb71d5427a4c0", "a": "a8ca406f5e8826f6daa3"}, {"re": "violation|inspector|нарушен|инспектор|акт", "screen": "satellite", "ans": "Violations — such as unauthorised intake, a different crop or damage to a canal — are recorded by an inspector with a photo, the GPS location and the time, or flagged by the satellite check. The association is notified, the higher department reviews the act, and a closed act is final.", "ans_ru": "Нарушения — например, самовольный забор воды, другая культура или повреждение канала — инспектор оформляет актом с фотографией, координатами и временем, либо их подсвечивает проверка по спутнику. Ассоциация получает извещение, акт рассматривает вышестоящее управление, а закрытый акт окончательный.", "a_ru": "4e9a486bad15042f1013", "a": "40c8be32e53b0b221697"}, {"re": "complain|жалоб", "screen": "complaints", "ans": "A farmer files a complaint from his phone — no water, late water, too little water, poor quality or damaged infrastructure — with a photo. It goes to the organization above the association, and if it is not handled in time it rises to the next level, keeping its original date.", "ans_ru": "Водопользователь подаёт жалобу с телефона: нет воды, вода с опозданием, мало воды, плохое качество или повреждение сооружений — с фотографией. Жалоба уходит в организацию над ассоциацией, а если её не рассмотрели вовремя, поднимается на следующий уровень с сохранением даты подачи.", "a_ru": "0034ff048249c4392e07", "a": "25b900a158005ee24aab"}, {"re": "assignment|task|задани", "screen": "complaints", "ans": "Field work runs through assignments — inspections, readings, repairs — each with an inspector, an object, a priority and a deadline. The inspector reports with a photo, and overdue assignments stay open and visible.", "ans_ru": "Работа в поле идёт через задания: проверки, снятие показаний, ремонт. У каждого — инспектор, объект, важность и срок. Инспектор отчитывается с фотографией, а просроченные задания остаются открытыми и на виду.", "a_ru": "32a3f7fe19453f174e38", "a": "450c9770e8ddb1c5be10"}, {"re": "organi[sz]ation|structure|hierarch|link scheme|tree|water object|canal|организац|структур|связ|канал", "screen": "links", "ans": "Water management is a hierarchy: the national agency, basin and state departments, hydrographic sections and water user associations. Each organization in IMIS knows who it reports to, and the link scheme shows how organizations are tied to basins, systems and canals, down to the water users.", "ans_ru": "Управление водой — это иерархия: Агентство, государственные и бассейновые управления, гидрографические участки и ассоциации водопользователей. Каждая организация знает, кому она подчиняется, а схема связей показывает, как организации связаны с бассейнами, системами и каналами — вплоть до водопользователей.", "a_ru": "4d8b1514704a0922643e", "a": "d3b7b416959d5bf1c9a0"}, {"re": "farmer|water user|plot|register|водопользоват|участ|регистр", "screen": "users", "ans": "A farmer registers with his passport, tax number and land certificate at the water user association and gets a unique number and one personal account. Each plot has a cadastral number, area, the canal that feeds it and its hydromodule district, and its outline is drawn on the map.", "ans_ru": "Водопользователь приносит в ассоциацию паспорт, ИНН и сертификат на землю и получает уникальный номер и один лицевой счёт. У каждого участка — кадастровый номер, площадь, канал, из которого он получает воду, и гидромодульный район, а его контур нанесён на карту.", "a_ru": "74373033e694c0eae095", "a": "8b429c7515b0afee1899"}, {"re": "right|permission|role|position|access|admin|прав|рол|должност|доступ|админ", "screen": "admin", "ans": "Rights in IMIS are flexible: every menu item and every action is a checkbox. A position gives a standard set of rights, a person can be given more — for example while replacing a colleague — and each person sees only his own organization and everything below it.", "ans_ru": "Права в системе гибкие: каждый пункт меню и каждое действие — это галочка. Должность даёт стандартный набор прав, человеку можно дать больше — например, на время замещения, — и каждый видит только свою организацию и всё, что ниже.", "a_ru": "538c835729a894e5fa41", "a": "dc32fe2d6b7f38432fd7"}, {"re": "audit|log|history|журнал|аудит", "screen": "reports", "ans": "Every action is written to the audit log: who did it, what changed, the old and new value, when and from where. The log can only be added to — nobody can edit or delete an entry, not even the administrator.", "ans_ru": "Каждое действие записывается в журнал аудита: кто, что изменил, прежнее и новое значение, когда и откуда. Журнал только пополняется — изменить или удалить запись не может никто, даже администратор.", "a_ru": "7a5c0284f55078588a3c", "a": "4fafcdfb5a3a5d8e6c2e"}, {"re": "report|excel|pdf|export|отчёт|отчет|выгруз", "screen": "reports", "ans": "Every section becomes a report — for a ten-day period, a month, a quarter or a year — exported to Excel or PDF, and a report always matches its section because both use the same rules.", "ans_ru": "Каждый раздел превращается в отчёт — за декаду, месяц, квартал или год — с выгрузкой в Excel или PDF, и отчёт всегда совпадает с разделом, потому что считается по тем же правилам.", "a_ru": "e9c79873e95968ec0d3e", "a": "f583cc7fa31bc704b6e5"}, {"re": "app|mobile|phone|offline|приложени|телефон", "screen": "admin", "ans": "In the field IMIS works through the mobile app. Farmers request water, confirm delivery, see their bills and file complaints; inspectors take readings, record violations and complete assignments. Readings and complaints entered without a signal are sent automatically when the connection returns.", "ans_ru": "В поле система работает через мобильное приложение. Водопользователи подают заявки, подтверждают получение воды, видят счета и подают жалобы; инспекторы снимают показания, оформляют нарушения и выполняют задания. Показания и жалобы без связи уходят сами, когда связь появится.", "a_ru": "4429f780654b59d2ba43", "a": "cbe9217fa7805bac6501"}, {"re": "asset|structure|pump|repair|актив|сооружен|насос", "screen": "assets", "ans": "IMIS keeps a register of irrigation assets — pump stations, hydraulic structures, canal sections and drainage — with capacity, value, wear, condition, inspection dates and every repair.", "ans_ru": "Система ведёт реестр сооружений: насосные станции, гидротехнические сооружения, участки каналов и дренаж — с пропускной способностью, стоимостью, износом, состоянием, датами осмотров и всеми ремонтами.", "a_ru": "835fba7dee67828b0a0b", "a": "efcd2cea204c43709b14"}, {"re": "tariff|price|cost|тариф|цен", "screen": "billing", "ans": "The tariff is set by the state, today five dirams per cubic metre by order number forty-eight. It is kept in the directories with its start date; every bill keeps the tariff it was calculated with, so a later change never rewrites old bills.", "ans_ru": "Тариф устанавливает государство — сейчас пять дирамов за кубометр по приказу номер сорок восемь. Он хранится в справочнике с датой начала действия; каждый счёт хранит свой тариф, поэтому новый тариф старые счета не меняет.", "a_ru": "2b79ddbd289667fefd9a", "a": "c0a03b76d93ff3879143"}];
window.OBSHCHIY={"ans": "I can tell you about any part of IMIS — water users and plots, contracts and requests, norms and plans, measurement, billing and payments, the map, satellite checks, complaints and permissions. Please ask about one of them.", "a": "c3fe4043091b25bda098", "screen": "intro", "ans_ru": "Я могу рассказать о любой части системы: водопользователи и участки, договоры и заявки, нормы и планы, учёт воды, начисления и оплата, карта, проверка по спутнику, жалобы и права. Спросите об одном из них.", "a_ru": "c08a75537ec6d1ad3fff"};

window.ZVUK_DOP={"Расскажу по этим разделам.": "4adeace056ba6df59d08", "Here are those sections.": "5836fa80d15b79aaaeb1"};
